'${(unitTotal+retailTotal).toStringAsFixed(2)} Box'))),const SizedBox(height:12),const Text('Production Unit Stock',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold)),for(final p in ps)Card(child:ListTile(title:Text(p['name']?.toString()??'Product'),subtitle:const Text('Opening + Production − Sales to Retail'),trailing:Text('${unit(p['id'].toString()).toStringAsFixed(2)} Box'))),const SizedBox(height:12),const Text('Retail Shop Stock',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold)),for(final s in shops)Card(child:ExpansionTile(title:Text(s['name']?.toString()??'Shop'),children:[for(final p in ps)ListTile(title:Text(p['name']?.toString()??'Product'),subtitle:const Text('Opening + Sales to Shop − Retail Sales'),trailing:Text('${shop(s['id'].toString(),p['id'].toString()).toStringAsFixed(2)} Box'))]))]);}))); }
